import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.BM5YPQmL.js";const u=JSON.parse('{"title":"8 个大应用：向导、direct、classic","description":"","frontmatter":{},"headers":[],"relativePath":"zh/manual/mega-apps.md","filePath":"zh/manual/mega-apps.md"}'),c={name:"zh/manual/mega-apps.md"};function d(n,e,i,l,p,r){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="_8-个大应用-向导、direct、classic" tabindex="-1">8 个大应用：向导、direct、classic <a class="header-anchor" href="#_8-个大应用-向导、direct、classic" aria-label="Permalink to &quot;8 个大应用：向导、direct、classic&quot;">​</a></h1><p>自 3.0.0 起，用户操作面围绕八个大应用组织。每个应用都打开同样的三扇门；用哪一扇，取决于你是在探索（向导）、写脚本（classic），还是想显式地绕过菜单（direct）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool                wizard: menus, checks, confirmations</span></span>
<span class="line"><span>ush&gt; disk-tool direct lsblk   explicit verbatim passthrough</span></span>
<span class="line"><span>ush&gt; disk-tool lsblk          classic dispatch = the historical command</span></span></code></pre></div><p>三种方式产生<strong>相同的服务输出</strong>——向导只是在其中增加了检测、安全确认与分组。</p><h2 id="向导-无参数" tabindex="-1">向导（无参数） <a class="header-anchor" href="#向导-无参数" aria-label="Permalink to &quot;向导（无参数）&quot;">​</a></h2><p>不带参数运行应用会打开一个意图向导：</p><ul><li>编号菜单：按单个数字键（<code>1</code>-<code>9</code>）选择，<code>q</code> 或 ESC 退出/返回。无需按回车。</li><li>破坏性路径（mkfs、abdisk、install、rm、电源操作）会询问目标名称，要求你<strong>重新输入一遍</strong>，然后输入单独的 <code>y</code>——其他任何输入都会中止。</li><li>向导读取的是与脚本相同的英文服务输出行，并且可以<strong>跨域</strong>：<code>update</code> 向导在检查更新之前，会先用 DHCP 修复缺失的 IP，用 <code>lsblk</code> + <code>abdisk</code> 修复缺失的 A/B 盘。</li><li>所有内容都经当前语言渲染：<code>lang zh</code> 会切换整个向导，菜单也不例外。</li></ul><h2 id="direct-显式透传" tabindex="-1">direct（显式透传） <a class="header-anchor" href="#direct-显式透传" aria-label="Permalink to &quot;direct（显式透传）&quot;">​</a></h2><p><code>&lt;app&gt; direct &lt;op&gt; [args...]</code> 会从参数行中去掉 <code>direct</code> 一词，然后严格按照历史命令的方式运行一个操作。当你希望脚本中的意图不言自明时使用它：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; update direct           the historical bare \`update\` (online flow)</span></span>
<span class="line"><span>ush&gt; sound-tool direct volume 50</span></span>
<span class="line"><span>ush&gt; sysdiag direct health watch</span></span></code></pre></div><h2 id="classic-逐字分发" tabindex="-1">classic（逐字分发） <a class="header-anchor" href="#classic-逐字分发" aria-label="Permalink to &quot;classic（逐字分发）&quot;">​</a></h2><p><code>&lt;app&gt; &lt;op&gt; [args...]</code> 在应用的表里查找该操作，并按历史拼写运行——输出与运行同名单命令应用逐字节一致。单命令应用仍保持注册（接口冻结规则：命令只增不删），因此 <code>lsblk</code> 与 <code>disk-tool lsblk</code> 是进入同一服务调用的两扇门。</p><p>未知的操作名会打印该应用的用法及其完整操作表：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; disk-tool nope</span></span>
<span class="line"><span>disk-tool: unknown op: nope</span></span>
<span class="line"><span>usage: disk-tool            (interactive menu)</span></span>
<span class="line"><span>       disk-tool direct &lt;op&gt; [args]   (explicit passthrough)</span></span>
<span class="line"><span>       disk-tool &lt;op&gt; [args]          (classic op dispatch)</span></span>
<span class="line"><span>ops:</span></span>
<span class="line"><span>  ahci</span></span>
<span class="line"><span>  nvme</span></span>
<span class="line"><span>  ...</span></span></code></pre></div><h2 id="逐应用详解" tabindex="-1">逐应用详解 <a class="header-anchor" href="#逐应用详解" aria-label="Permalink to &quot;逐应用详解&quot;">​</a></h2><h3 id="update——ota-向导" tabindex="-1">update——OTA 向导 <a class="header-anchor" href="#update——ota-向导" aria-label="Permalink to &quot;update——OTA 向导&quot;">​</a></h3><p><code>update</code>（无参数）用五步走完整个更新意图：</p><ol><li><strong>网络</strong>——读取 IP 状态；若地址为 0.0.0.0，则提供 DHCP 修复，然后复查。</li><li><strong>A/B 盘</strong>——读取 <code>update status</code>；当 A/B 盘缺失时列出 <code>lsblk</code>，询问设备名（重输 + 确认）并运行 <code>abdisk</code>，然后复查直到其存在。</li><li><strong>DNS</strong>——解析当前的 <code>config get update_url</code> 取值，并对更新主机做域名解析。</li><li><strong>检查</strong>——<code>checkupdate</code>：已是最新则以 OK 结束向导。</li><li><strong>安装</strong>——经确认的在线更新，随后经确认重启进入新槽位。</li></ol><p>经典面：<code>update status</code>、<code>update --local &lt;path&gt;</code>、<code>update &lt;anything&gt;</code> = 逐字 OTA 操作。</p><h3 id="disk-tool——磁盘与文件系统" tabindex="-1">disk-tool——磁盘与文件系统 <a class="header-anchor" href="#disk-tool——磁盘与文件系统" aria-label="Permalink to &quot;disk-tool——磁盘与文件系统&quot;">​</a></h3><p>菜单：lsblk / parted / mkfs 子菜单（FAT32、exFAT、ext4——双重确认）/ 挂载管理器（list、mount、umount、fatmount、fatstat）/ fsck / dskstat / A/B 管理器（status、create、abcfg）。</p><p>经典表：全部 23 个块设备操作（<code>ahci</code> .. <code>abcfg</code>）加 6 个文件系统操作（<code>mount</code>、<code>mounts</code>、<code>umount</code>、<code>fatmount</code>、<code>fatstat</code>、<code>tree</code>）。</p><h3 id="net-tool——连通性" tabindex="-1">net-tool——连通性 <a class="header-anchor" href="#net-tool——连通性" aria-label="Permalink to &quot;net-tool——连通性&quot;">​</a></h3><p>菜单：显示 IP / DHCP / 静态 IP（地址、掩码、网关逐字段采集）/ DNS / WiFi 管理器（status、scan、test、sdio）/ 蓝牙（status、usb、uart、test）/ 防火墙 / route + arp / 连通性测试（ping、wget、ssh、dnstest——ping 和 wget 走的是历史应用所用的同一座 NETCMD 桥）。</p><p>经典表：14 个网络操作（<code>arp</code> .. <code>sshd</code>）加 <code>wifi</code> 和 <code>bt</code>。</p><h3 id="sound-tool——音频" tabindex="-1">sound-tool——音频 <a class="header-anchor" href="#sound-tool——音频" aria-label="Permalink to &quot;sound-tool——音频&quot;">​</a></h3><p>菜单：设备概览 / 音量（仅数字校验）/ 440 Hz 测试音 / 各驱动状态（HDA、AC&#39;97、SB16、ES1370、virtio-snd、USB audio）/ 自检（RW 回环、采样率精度，或依次运行每个驱动各自的自检）。</p><p>经典表：全部 17 个声音操作（<code>sound</code> .. <code>sample_rate_test</code>）。</p><h3 id="files——文件管理器" tabindex="-1">files——文件管理器 <a class="header-anchor" href="#files——文件管理器" aria-label="Permalink to &quot;files——文件管理器&quot;">​</a></h3><p>菜单：ls / tree / 磁盘用量（df + du）/ 复制 / 移动 / 删除（带确认）/ edit（全屏编辑器）/ 信息 + 权限（先 stat，再可选 chmod，带八进制校验）。</p><p>这里的分发是对历史程序的 fork + execve（<code>run</code> 机制），因为文件工具是真实程序而非服务调用——编辑器是交互式的。经典表：<code>ls</code>、<code>tree</code>、<code>df</code>、<code>du</code>、<code>cp</code>、<code>mv</code>、<code>rm</code>、<code>edit</code>、<code>stat</code>、<code>chmod</code>。</p><h3 id="sysdiag——系统诊断" tabindex="-1">sysdiag——系统诊断 <a class="header-anchor" href="#sysdiag——系统诊断" aria-label="Permalink to &quot;sysdiag——系统诊断&quot;">​</a></h3><p>菜单：健康快照 / 内核日志 / 内存画像（mem + frag + heap）/ 调度器 + 同步统计 / 崩溃记录 / 日志工具（logcat、logctl、health export、health watch）/ 自检实验室（memtest、heaptest、fstest、vmtest——可单个运行，也可四个依次全跑）。</p><p>经典表：全部 39 个诊断操作，加上 health、dmesg/logcat/logctl 与 watchdog——共 46 项。<code>crashtest</code>（故意注入 panic）只能通过 classic/direct 触达，这是有意为之。</p><h3 id="hwinfo——硬件清单" tabindex="-1">hwinfo——硬件清单 <a class="header-anchor" href="#hwinfo——硬件清单" aria-label="Permalink to &quot;hwinfo——硬件清单&quot;">​</a></h3><p>菜单：系统摘要（uname -a + 内存）/ 时钟源（RTC、HPET、PM timer、TSC）/ PCI（lspci、pcidump、pcibars、pcie）/ ACPI / SMBus-I2C / USB / 摄像头与老式输入 / 显示 + 字体 + 编码。</p><p>经典表：横跨显示、时间、网络、诊断、USB、摄像头与输入各面的 26 个只读操作。</p><h3 id="power——电源管理" tabindex="-1">power——电源管理 <a class="header-anchor" href="#power——电源管理" aria-label="Permalink to &quot;power——电源管理&quot;">​</a></h3><p>菜单：关机 / 重启 / 停机（每项都需单独输入 y 确认）/ 睡眠 N 秒（校验为纯数字）/ 电源路径自检（每项都有各自的警告 + 确认——这些探测会真实演练电源路径）。</p><p>经典表：<code>shutdown</code>、<code>poweroff</code>、<code>reboot</code>、<code>halt</code>、<code>sleep</code>、<code>poweroff_test</code>、<code>suspend_test</code>、<code>halt_test</code>、<code>reboot_test</code>。</p><h2 id="i18n" tabindex="-1">i18n <a class="header-anchor" href="#i18n" aria-label="Permalink to &quot;i18n&quot;">​</a></h2><p>向导的每一行都经当前 locale 渲染。切换方式：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ush&gt; lang zh        (menus, prompts and verdicts become Chinese)</span></span>
<span class="line"><span>ush&gt; lang en        (back to English)</span></span></code></pre></div><p>缺失的翻译会回退到英文，再回退到键本身——未翻译的应用绝不会崩溃或打印乱码。</p>`,44)])])}const g=a(c,[["render",d]]);export{u as __pageData,g as default};
